package bowling

import "errors"

// Game keeps track of the rolls in a game of bowling and
// can compute the total score once the game is complete.
type Game struct {
	rolls      []int // all rolls, in order
	frame      int   // index (0-based) of the frame currently being played
	frameRolls []int // rolls made in the current frame
	done       bool  // true once the tenth frame is complete
}

func NewGame() *Game {
	return &Game{}
}

var (
	errNegativeRoll   = errors.New("Negative roll is invalid")
	errTooManyPins    = errors.New("Pin count exceeds pins on the lane")
	errGameIsOver     = errors.New("Cannot roll after game is over")
	errIncompleteGame = errors.New("Score cannot be taken until the end of the game")
)

func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errTooManyPins
	}
	if g.done {
		return errGameIsOver
	}

	if len(g.frameRolls) == 1 {
		first := g.frameRolls[0]
		if g.frame < 9 {
			// Second roll of a normal frame: the lane still has 10-first pins.
			if first+pins > 10 {
				return errTooManyPins
			}
		} else {
			// Tenth frame.
			if first == 10 {
				// First bonus roll after a strike: fresh lane, no constraint beyond 0-10.
			} else if first+pins > 10 {
				return errTooManyPins
			}
		}
	} else if len(g.frameRolls) == 2 {
		// Only possible in the tenth frame.
		first, second := g.frameRolls[0], g.frameRolls[1]
		if first == 10 && second != 10 {
			// Second bonus roll after a non-strike first bonus: constrained.
			if second+pins > 10 {
				return errTooManyPins
			}
		}
		// If first was a strike and second was a strike, or first+second is a spare
		// (first != 10), the third roll is a fresh-lane bonus: no constraint.
	}

	g.rolls = append(g.rolls, pins)
	g.frameRolls = append(g.frameRolls, pins)

	if g.frameComplete() {
		g.frameRolls = nil
		g.frame++
		if g.frame == 10 {
			g.done = true
		}
	}
	return nil
}
